import React, { useState, useEffect } from 'react';
import './VideoPlayer.css';

const VideoPlayer = () => {
    const [videoFile, setVideoFile] = useState('');
    const [videoSrc, setVideoSrc] = useState('');
    const [videos, setVideos] = useState([]);
    const [showList, setShowList] = useState(true); // New state to control list visibility

    const fetchVideos = async () => {
        try {
            const response = await fetch('http://localhost:3000/api/videos');
            const data = await response.json();
            setVideos(data);
        } catch (error) {
            console.error('Error fetching videos:', error);
        }
    };

    useEffect(() => {
        fetchVideos();
    }, []);

    const handleRefresh = () => {
        fetchVideos();
        setShowList(!showList); // Toggle list visibility to force refresh
    };

    const handleSubmit = (e) => {
        e.preventDefault();
        setVideoSrc(`http://localhost:3000/video/${videoFile}`);
    };

    return (
        <div className="video-container">
            <div className="controls">
                <button onClick={handleRefresh} className="refresh-btn">
                    Refresh Videos
                </button>
            </div>
            
            <div className="video-list" key={showList}> {/* Added key prop to force refresh */}
                <h2>Available Videos</h2>
                <ul>
                    {videos.map((video) => (
                        <li key={video.name}>
                            {video.name} ({Math.round(video.size / 1024 / 1024)} MB)
                        </li>
                    ))}
                </ul>
            </div>

            <form onSubmit={handleSubmit}>
                <input
                    type="text"
                    value={videoFile}
                    onChange={(e) => setVideoFile(e.target.value)}
                    placeholder="Enter video filename"
                />
                <button type="submit">Stream Video</button>
            </form>

            {videoSrc && (
                <video width="100%" controls autoPlay>
                    <source src={videoSrc} type="video/mp4" />
                    Your browser does not support the video tag.
                </video>
            )}
        </div>
    );
};

export default VideoPlayer;
